// ── Measuring Core Web Vitals with PerformanceObserver ────────
function measureWebVitals(reportFn) {
  // LCP — fires multiple times; the LAST entry is the actual LCP
  new PerformanceObserver((list) => {
    const entries = list.getEntries();
    const lcp = entries[entries.length - 1];
    reportFn({ name: 'LCP', value: lcp.startTime, element: lcp.element });
  }).observe({ type: 'largest-contentful-paint', buffered: true });

  // CLS — accumulate score, exclude user-triggered shifts
  let clsScore = 0;
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (!entry.hadRecentInput) {
        clsScore += entry.value;
      }
    }
    reportFn({ name: 'CLS', value: clsScore });
  }).observe({ type: 'layout-shift', buffered: true });

  // INP — track worst interaction latency across session
  let worstInp = 0;
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (entry.interactionId && entry.duration > worstInp) {
        worstInp = entry.duration;
        reportFn({ name: 'INP', value: worstInp });
      }
    }
  }).observe({ type: 'event', buffered: true, durationThreshold: 16 });
}

// Send to your analytics endpoint
measureWebVitals(({ name, value }) => {
  console.log(`${name}: ${value.toFixed(1)}${name === 'CLS' ? '' : 'ms'}`);
  // navigator.sendBeacon('/analytics', JSON.stringify({ name, value }));
});

