// ── Image element best practices ──────────────────────────────
function createOptimizedHeroImage(src, altText, width, height) {
  const img = document.createElement('img');
  img.src          = src;
  img.alt          = altText;
  img.width        = width;          // reserve space → prevents CLS
  img.height       = height;         // reserve space → prevents CLS
  img.fetchPriority = 'high';        // top of fetch queue → better LCP
  img.decoding     = 'async';        // decode off main thread
  // Do NOT set loading="lazy" on the LCP image!
  return img;
}

// ── Long task splitting for better INP ────────────────────────
// BAD: one 300ms synchronous loop blocks the main thread
function processLargeDataset(items) {
  items.forEach(item => heavyComputation(item)); // blocks for 300ms
}

// GOOD: yield to browser between chunks using scheduler
async function processLargeDatasetAsync(items, chunkSize = 50) {
  for (let i = 0; i < items.length; i += chunkSize) {
    const chunk = items.slice(i, i + chunkSize);
    chunk.forEach(item => heavyComputation(item));
    // Yield: let browser handle any pending user interactions
    await new Promise(resolve => setTimeout(resolve, 0));
  }
}

